INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES
(32859,0,0,'%s becomes enraged!',16,0,100,0,0,0,10677,0,'combat Enrage'),
(32860,0,0,'Relax, mon, I be makin\' dis quick.',12,0,100,0,0,0,50171,0,'on Aggro Text'),
(32863,0,0,'%s becomes enraged!',16,0,100,0,0,0,10677,0,'combat Enrage'),
(32868,0,0,'Don\'t move, little adventurer. I have the death you seek.',12,0,100,0,0,0,34476,0,'on Aggro Text'),
(32888,1,0,'Intruders! Good, I was getting bored...',12,0,50,0,0,0,840,0,'combat Text'),
(32888,1,1,'Masters, I pledge this Pin to you!',14,0,50,0,0,0,835,0,'combat Text'),
(32989,0,0,'Ya be messin\' with Tzu-Tzu? It no matter...Aetherion\'s here,mon.We gonna roll on ya refugee camp an\' then bring the hurt to ya Lor\'demal.But first ya die!',12,0,100,0,0,0,33219,0,'on Aggro Text'),
(33079,0,0,'%s becomes enraged!',16,0,100,0,0,0,10677,0,'combat Enrage'),
(34033,0,0,'Your flesh is forfeit!',12,0,100,15,0,0,34163,0,'Teegan Holloway Aggro'),
(34033,1,0,'I said, SEARCH the bodies BEFORE you eat them!',12,0,100,5,0,0,34167,0,'Teegan Holloway Script'),
(34033,1,1,'Leave no stone unturned. I mean that literally, you heaps of decay! Tear this place apart if you have to.',12,0,100,5,0,0,34168,0,'Teegan Holloway Script');
